<script setup>
import { ref } from 'vue'
import { searchAdminMessages } from '../../api/admin-api'
const keyword = ref(''); const loading = ref(false); const error = ref(''); const results = ref([]); const total = ref(0); const hasSearched = ref(false); const pageNo = ref(1); const pageSize = ref(20)
async function search() { const value = keyword.value.trim(); if (!value) return; pageNo.value = 1; await loadResults() }
async function loadResults() { const value = keyword.value.trim(); if (!value) return; hasSearched.value = true; loading.value = true; error.value = ''; try { const result = await searchAdminMessages({ keyword: value, pageNo: pageNo.value, pageSize: pageSize.value }); results.value = result?.data?.records || []; total.value = result?.data?.total || 0 } catch (exception) { error.value = exception.message || '&#25628;&#32034;&#22833;&#36133;' } finally { loading.value = false } }
function handlePageChange(nextPage) { if (nextPage === pageNo.value) return; pageNo.value = nextPage; loadResults() }
function clear() { keyword.value = ''; results.value = []; total.value = 0; error.value = ''; hasSearched.value = false; pageNo.value = 1 }
</script>
<template><section class="message-search"><div class="panel-header"><h2>&#28040;&#24687;&#25628;&#32034;</h2><p>&#22312;&#20840;&#37096;&#26410;&#25764;&#22238;&#32842;&#22825;&#28040;&#24687;&#20013;&#25628;&#32034;</p></div><div class="search-row"><el-input v-model="keyword" clearable placeholder="&#36755;&#20837;&#28040;&#24687;&#20851;&#38190;&#35789;" @keyup.enter="search"/><el-button type="primary" :loading="loading" :disabled="!keyword.trim()" @click="search">&#25628;&#32034;</el-button><el-button :disabled="!keyword && !results.length" @click="clear">&#28165;&#31354;</el-button></div><p v-if="error" class="error">{{ error }}</p><p v-else-if="hasSearched && !loading" class="summary">&#20849;&#25214;&#21040; {{ total }} &#26465;&#21305;&#37197;&#28040;&#24687;</p><el-table v-if="results.length" :data="results" class="data-table" row-key="messageId"><el-table-column prop="sessionTitle" label="&#20250;&#35805;" min-width="150"/><el-table-column prop="content" label="&#28040;&#24687;&#20869;&#23481;" min-width="300"/><el-table-column prop="senderId" label="&#21457;&#36865;&#32773;" min-width="120"/><el-table-column prop="senderRole" label="&#35282;&#33394;" width="100"/><el-table-column prop="createTime" label="&#21457;&#36865;&#26102;&#38388;" min-width="170"/></el-table><el-pagination v-if="results.length && total > pageSize" class="pagination" layout="prev, pager, next" :current-page="pageNo" :page-size="pageSize" :total="total" :disabled="loading" @current-change="handlePageChange"/><div v-if="!results.length && hasSearched && !loading && !error" class="empty">&#26242;&#26080;&#21305;&#37197;&#28040;&#24687;</div></section></template>
<style scoped>.message-search{padding:1rem}.panel-header{margin-bottom:1rem}.panel-header h2{margin:0;color:var(--color-ink)}.panel-header p{margin:.35rem 0 0;color:var(--color-muted);font-size:.9rem}.search-row{display:flex;gap:.5rem;max-width:680px}.search-row :deep(.el-input){flex:1}.summary{margin:1rem 0 .5rem;color:var(--color-muted)}.error{color:#dc2626}.empty{padding:2rem;color:var(--color-faint);text-align:center}</style>
